insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template,published) values('d7010000-0000-4000-8000-000000000001','daily','Daily Japanese','日常会話','Talk about routines, interests and everyday life.','毎日の生活や好きなことを話しましょう。','N5–N4','こんにちは。{今日|きょう}は何をしましたか。','Hello. What did you do today?','A friendly everyday conversation partner. Discuss routines, hobbies and plans.',true) on conflict do nothing;
insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template,published) values('d7010000-0000-4000-8000-000000000002','interview','Japanese job interview','日本語の就職面接','Practise truthful introductions and professional answers.','本当の経験を使って自己紹介や受け答えを練習します。','N3–N2','本日はよろしくお願いいたします。自己紹介をお願いできますか。','Thank you for coming. Could you introduce yourself?','A respectful job interviewer. Ask about real experience and motivation. Never invent qualifications or evaluate hiring eligibility.',true) on conflict do nothing;
insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template,published) values('d7010000-0000-4000-8000-000000000003','business','Business Japanese','ビジネス日本語','Discuss meetings, requests and professional communication.','会議や依頼など、仕事でのやり取りを練習します。','N2–N1','お疲れさまです。次の{会議|かいぎ}について、ご相談してもよろしいでしょうか。','Thank you for your work. May I consult you about the next meeting?','A professional colleague discussing meetings and requests. Use contextually appropriate register, with nuanced language for N2/N1.',true) on conflict do nothing;
insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template,published) values('d7010000-0000-4000-8000-000000000004','restaurant','Restaurant conversations','レストランの会話','Order food, ask questions and clarify requests.','注文やメニューについての質問を練習します。','N5–N3','いらっしゃいませ。何名様ですか。','Welcome. How many people are in your party?','A polite restaurant staff member. Practise reservations, orders and clarification. Do not give medical allergy assurances.',true) on conflict do nothing;
insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template,published) values('d7010000-0000-4000-8000-000000000005','city-hall','City hall procedures','市役所での手続き','Practise asking staff what documents to check.','必要な書類の確認など、窓口での言葉を練習します。','N4–N2','こんにちは。今日はどのようなご用件でしょうか。','Hello. How can I help you today?','A city hall language role-play. Teach how to ask an official which documents are needed. Do not determine legal or immigration eligibility or request identifiers.',true) on conflict do nothing;
insert into public.ai_scenarios(id,slug,title,title_ja,description,description_ja,suggested_level,opening,opening_translation,prompt_template,published) values('d7010000-0000-4000-8000-000000000006','workplace','Workplace communication & safety','職場の連絡と安全','Ask for clarification and report concerns respectfully.','指示の確認や心配なことの報告を練習します。','N4–N2','お疲れさまです。作業の前に、確認したいことはありますか。','Before starting work, is there anything you want to clarify?','A workplace colleague. Practise asking supervisors for clarification and reporting concerns. Never provide hazardous operational or clinical instructions; defer to qualified supervision and workplace procedures.',true) on conflict do nothing;
